DROP TRIGGER IF EXISTS bookkeeping_batch_final_checks_no_update;
DROP TRIGGER IF EXISTS bookkeeping_batch_final_checks_no_delete;
ALTER TABLE bookkeeping_batch_final_checks RENAME TO bookkeeping_batch_final_checks_legacy;
CREATE TABLE bookkeeping_batch_final_checks (
  id INTEGER PRIMARY KEY,
  run_id INTEGER NOT NULL REFERENCES bookkeeping_batch_runs(id),
  check_name TEXT NOT NULL CHECK(check_name IN ('audit_chain','trial_balance','reconciliation','vat')),
  ok INTEGER NOT NULL CHECK(ok IN (0,1)),
  detail_json TEXT NOT NULL,
  created_at TEXT NOT NULL
);
INSERT INTO bookkeeping_batch_final_checks(id,run_id,check_name,ok,detail_json,created_at) SELECT id,run_id,check_name,ok,detail_json,created_at FROM bookkeeping_batch_final_checks_legacy;
DROP TABLE bookkeeping_batch_final_checks_legacy;
CREATE INDEX idx_bookkeeping_batch_final_checks_run ON bookkeeping_batch_final_checks(run_id,id);
CREATE TRIGGER bookkeeping_batch_final_checks_no_update BEFORE UPDATE ON bookkeeping_batch_final_checks BEGIN SELECT RAISE(ABORT, 'bookkeeping batch final checks are immutable'); END;
CREATE TRIGGER bookkeeping_batch_final_checks_no_delete BEFORE DELETE ON bookkeeping_batch_final_checks BEGIN SELECT RAISE(ABORT, 'bookkeeping batch final checks are append-only'); END;
